scores[i] * weights[i]; weight_sum += weights[i]; } } if weight_sum > 0.0 { weighted_sum / weight_sum } else { 0.0 } } /// Rank content by fusion score with given weights fn rank_content( content: &[SimulatedScores], weights: &[f32; NUM_EMBEDDERS], ) -> Vec<(usize, f32, ContentType)> { let mut ranked: Vec<_> = content .iter() .map(|c| { let score = compute_fusion_score(&c.scores, weights); (c.id, score, c.content_type) }) .collect(); ranked.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)); ranked } /// Find the rank of the first item with the target content type fn find_first_rank(ranked: &[(usize, f32, ContentType)], target: ContentType) -> Option<usize> { ranked .iter() .position(|(_, _, ct)| *ct == target) .map(|pos| pos + 1) // 1-indexed rank } /// Compute MRR for a target content type fn compute_mrr(ranked: &[(usize, f32, ContentType)], target: ContentType) -> f32 { match find_first_rank(ranked, target) { Some(rank) => 1.0 / rank as f32, None => 0.0, } } /// Compute Precision@K for a target content type fn compute_precision_at_k( ranked: &[(usize, f32, ContentType)], target: ContentType, k: usize, ) -> f32 { let top_k = ranked.iter().take(k); let relevant_count = top_k.filter(|(_, _, ct)| *ct == target).count(); relevant_count as f32 / k as f32 } /// Results for a single profile test #[derive(Debug)] struct ProfileTestResult { profile_name: String, target_content_type: ContentType, mrr: f32, first_rank: Option<usize>, precision_at_3: f32, precision_at_5: f32, precision_at_10: f32, } /// Generate test corpus with mixed content types fn generate_test_corpus() -> Vec<SimulatedScores> { let mut corpus = Vec::new(); let mut id = 0; // Generate content for each type with varying base scores for content_type in ContentType::all() { // Each type gets 10 items with base scores between 0.4 and 0.6 for i in 0..10 { let base_score = 0.4 + (i as f32 * 0.02); corpus.push(SimulatedScores::for_content_type( content_type, id, base_score, )); id += 1; } } corpus } /// Test a specific weight profile against the corpus fn test_profile( profile_name: &str, corpus: &[SimulatedScores], target_content_type: ContentType, ) -> ProfileTestResult { let weights = get_weight_profile(profile_name) .unwrap_or_else(|_| panic!("Profile {} not found", profile_name)); let ranked = rank_content(corpus, &weights); ProfileTestResult { profile_name: profile_name.to_string(), target_content_type, mrr: compute_mrr(&ranked, target_content_type), first_rank: find_first_rank(&ranked, target_content_type), precision_at_3: compute_precision_at_k(&ranked, target_content_type, 3), precision_at_5: compute_precision_at_k(&ranked, target_content_type, 5), precision_at_10: compute_precision_at_k(&ranked, target_content_type, 10), } } /// Print results as a formatted table fn print_results_table(results: &[ProfileTestResult]) { println!("
