 edges_per_sec: f64, } /// Combined report for all graph linking benchmarks. #[derive(Debug, Clone, Default, Serialize, Deserialize)] pub struct GraphLinkingReport { /// NN-Descent algorithm metrics. pub nn_descent: NNDescentMetrics, /// EdgeBuilder metrics. pub edge_builder: EdgeBuilderMetrics, /// BackgroundGraphBuilder metrics. pub background_builder: BackgroundBuilderMetrics, /// Graph expansion stage metrics. pub graph_expansion: GraphExpansionMetrics, /// Weight projection metrics. pub weight_projection: WeightProjectionMetrics, /// R-GCN metrics. pub rgcn: RGCNMetrics, /// Scale tier used for benchmarking. pub tier: Option<String>, /// Timestamp of benchmark run. pub timestamp: String, /// Total benchmark duration in seconds. pub total_duration_secs: f64, } impl GraphLinkingReport { /// Create a new empty report. pub fn new() -> Self { Self { timestamp: chrono::Utc::now().to_rfc3339(), ..Default::default() } } /// Set the tier. pub fn with_tier(mut self, tier: ScaleTier) -> Self { self.tier = Some(tier.name().to_string()); self } /// Convert to JSON. pub fn to_json(&self) -> serde_json::Value { serde_json::to_value(self).unwrap_or(serde_json::Value::Null) } /// Generate markdown report. pub fn to_markdown(&self) -> String { let mut md = String::new(); md.push_str("# Graph Linking Benchmark Report

