Graph Expansion:"); println!( " Expansion ratio: {:.2}x", self.graph_expansion.expansion_ratio ); println!(" Latency: {}", self.graph_expansion.latency); } } /// Latency tracker for collecting measurements. #[derive(Debug, Default)] pub struct LatencyTracker { samples: Vec<Duration>, } impl LatencyTracker { /// Create a new tracker. pub fn new() -> Self { Self { samples: Vec::new(), } } /// Record a duration sample. pub fn record(&mut self, duration: Duration) { self.samples.push(duration); } /// Record elapsed time from an instant. pub fn record_since(&mut self, start: std::time::Instant) { self.samples.push(start.elapsed()); } /// Get computed statistics. pub fn stats(&self) -> LatencyStats { LatencyStats::from_durations(&self.samples) } /// Get number of samples. pub fn count(&self) -> usize { self.samples.len() } /// Clear all samples. pub fn clear(&mut self) { self.samples.clear(); } } #[cfg(test)] mod tests { use super::*; #[test] fn test_latency_stats_from_durations() { let durations = vec![ Duration::from_micros(100), Duration::from_micros(200), Duration::from_micros(150), Duration::from_micros(300), Duration::from_micros(250), ]; let stats = LatencyStats::from_durations(&durations); assert_eq!(stats.count, 5); assert_eq!(stats.min_us, 100); assert_eq!(stats.max_us, 300); assert_eq!(stats.mean_us, 200); assert_eq!(stats.p50_us, 200); } #[test] fn test_latency_tracker() { let mut tracker = LatencyTracker::new(); tracker.record(Duration::from_millis(10)); tracker.record(Duration::from_millis(20)); tracker.record(Duration::from_millis(15)); assert_eq!(tracker.count(), 3); let stats = tracker.stats(); assert_eq!(stats.count, 3); assert!(stats.mean_us >= 10_000); } #[test] fn test_report_to_markdown() { let report = GraphLinkingReport::new(); let md = report.to_markdown(); assert!(md.contains("Graph Linking Benchmark Report")); assert!(md.contains("NN-Descent")); assert!(md.contains("EdgeBuilder")); } #[test] fn test_report_to_json() { let mut report = GraphLinki