//! Comparative benchmark harness. //! //! Main entry point for running side-by-side comparisons of multi-space //! and single-embedder systems. use serde::{Deserialize, Serialize}; use std::collections::HashMap; use crate::config::{BenchmarkConfig, Tier}; use crate::metrics::ScalingMetrics; use crate::scaling::DegradationComparison; use super::scaling::{ScalingAnalysisResults, ScalingRunner}; /// Main benchmark harness for comparative analysis. pub struct BenchmarkHarness { config: BenchmarkConfig, } impl BenchmarkHarness { /// Create a new harness with default CI config. pub fn new() -> Self { Self { config: BenchmarkConfig::ci(), } } /// Create with specific config. pub fn with_config(config: BenchmarkConfig) -> Self { Self { config } } /// Create for full benchmark (all tiers). pub fn full() -> Self { Self { config: BenchmarkConfig::full(), } } /// Run the full benchmark suite. pub fn run_full_suite(&self) -> BenchmarkResults { let scaling_runner = ScalingRunner::new(self.config.clone()); // Run both systems let single_results = scaling_runner.run_single_embedder(); let multi_results = scaling_runner.run_multi_space(); // Build comparative results let comparison = self.build_comparison(&single_results, &multi_results); BenchmarkResults { config: self.config.clone(), single_embedder: single_results, multi_space: multi_results, comparison, } } /// Run scaling analysis only. pub fn run_scaling_analysis(&self) -> ScalingAnalysisResults { let scaling_runner = ScalingRunner::new(self.config.clone()); scaling_runner.run_multi_space() } /// Build comparison between two systems. fn build_comparison( &self, single: &ScalingAnalysisResults, multi: &ScalingAnalysisResults, ) -> ComparativeResults { // Compute improvement metrics per tier let mut tier_improvements = HashMap::new(); for tier_config in &self.config.tiers { let tier = tier_config.tier; if let (Some(single_metrics), Some(multi_metrics)) = (single.get_tier_metrics(tier), multi.get_tier_metrics(tier)) { tier_improvements.insert( tier, TierImprovement { precision_10: compute_improvement( single_metrics .retrieval .precision_at .get(&10) .copied() .unwrap_or(0.0), multi_metrics .retrieval .precision_at .get(&10) .copied() .unwrap_or(0.0), ), recall_10: compute_improvement( single_metrics .retrieval .recall_at .get(&10) .copied() .unwrap_or(0.0), multi_metrics .retrieval .recall_at .get(&10) .copied() .unwrap_or(0.0), ), mrr: compute_improvement( single_metrics.retrieval.mrr, multi_metrics.retrieval.mrr, ), purity: compute_improvement( single_metrics.clustering.purity, multi_metrics.clustering.purity, ), nmi: compute_improvement( single_metrics.clustering.nmi, multi_metrics.clustering.nmi, ), }, ); } } // Compute degradation comparison let degradation_comparison = if let (Some(ref single_deg), Some(ref multi_deg)) = (&single.degradation, &multi.degradation) { Some(DegradationComparison::compare(multi_deg, single_deg)) } else { None }; // Compute scaling advantage factor let scaling_advantage = if let (Some(ref single_deg), Some(ref multi_deg)) = (&single.degradation, &multi.degradation) { multi_deg.scaling_advantage_factor(single_deg) } else { None }; // Determine winner based on scaling (if meaningful) or metric improvements // Need at least 2 tiers for meaningful scaling comparison let has_meaningful_scaling = single.tier_results.len() >= 2 && multi.tier_results.len() >= 2; let winner = if has_meaningful_scaling { if let (Some(ref single_deg), Some(ref multi_deg)) = (&single.degradation, &multi.degradation) { // Use scaling analysis for multi-tier benchmarks if multi_deg.scales_better_than(single_deg) { "multi-space".to_string() } else { "single-embedder".to_string() } } else { "unknown".to_string() } } else { // For single-tier tests, use metric improvements to determine winner // Multi-space wins if it has better retrieval or clustering metrics overall let overall_improvement = compute_overall_improvement(&tier_improvements); if overall_improvement > 0.0 { "multi-space".to_string() } else if overall_improvement < 0.0 { "single-embedder".to_string() } else { "tie".to_string() } }; // Compute overall improvement let overall_improvement = compute_overall_improvement(&tier_improvements); // Memory overhead let memory_overhead = if let (Some(ref single_mem), Some(ref multi_mem)) = (&single.memory_report, &multi.memory_report) { if let (Some(single_first), Some(multi_first)) = (single_mem.profiles.first(), multi_mem.profiles.first()) { if single_first.total_bytes > 0 { Some(multi_first.total_bytes as f64 / single_first.total_bytes as f64) } else { None } } else { None } } else { None }; ComparativeResults { tier_improvements, degradation_comparison, scaling_advantage_factor: scaling_advantage, winner, overall_improvement, memory_overhead_factor: memory_overhead, } } } impl Default for BenchmarkHarness { fn default() -> Self { Self::new() } } /// Complete benchmark results. #[derive(Debug, Clone, Serialize, Deserialize)] pub struct BenchmarkResults { /// Configuration used. pub config: BenchmarkConfig, /// Single-embedder results. #[serde(skip)] pub single_embedder: ScalingAnalysisResults, /// Multi-space results. #[serde(skip)] pub multi_space: ScalingAnalysisResults, /// Comparative analysis. pub comparison: ComparativeResults, } impl BenchmarkResults { /// Get summary string. pub fn summary(&self) -> String { let mut s = String::new(); s.push_str(&format!( "Benchmark Results: {} vs {}
", self.multi_space.system_name, self.single_embedder.system_name )); s.push_str(&format!("Winner: {}
