 = compute_recency_data(&dataset, settings); let metrics = crate::metrics::temporal::compute_all_temporal_metrics( &recency_data, &PeriodicBenchmarkData::default(), &SequenceBenchmarkData::default(), 0.0, ); // Test adaptive half-life if enabled let adaptive_half_life_results = if test_adaptive { let sizes = corpus_sizes.unwrap_or_else(|| vec![1000, 5000, 10000, 50000]); Some(run_adaptive_half_life_test( &sizes, settings, dataset_config.seed, )) } else { None }; // Time window tests let time_window_results = run_time_window_tests(&dataset, settings); E2RecencyBenchmarkResults { decay_function_scores, best_decay_function, decay_accuracy: metrics.recency.decay_accuracy, recency_weighted_mrr: metrics.recency.recency_weighted_mrr, freshness_precision_at: metrics.recency.freshness_precision_at, adaptive_half_life_results, time_window_results, timing_ms: start.elapsed().as_millis() as u64, } } fn evaluate_decay_function( dataset: &TemporalBenchmarkDataset, function: &str, half_life_ms: i64, ) -> f64 { let mut scores = Vec::new(); for query in &dataset.recency_queries { let query_ts = query.query_timestamp.timestamp_millis(); let mut scored: Vec<_> = dataset .memories .iter() .filter(|m| m.timestamp <= query.query_timestamp) .map(|m| { let ts = m.timestamp.timestamp_millis(); let age_ms = query_ts - ts; let decay_score = match function { "linear" => 1.0 - (age_ms as f64 / (half_life_ms * 4) as f64).min(1.0), "exponential" => (-0.693 * age_ms as f64 / half_life_ms as f64).exp(), "step" => { if age_ms < half_life_ms { 1.0 } else if age_ms < half_life_ms * 2 { 0.5 } else { 0.1 } } _ => (-0.693 * age_ms as f64 / half_life_ms as f64).exp(), }; (m.id, decay_score, ts) }) .collect(); scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)); // Compute MRR for this query for (pos, (id, _, _)) in scored.iter().enumerate() { if query.fresh_memory_ids.contains(id) { scores.push(1.0 / (pos + 1) as f64); break; } } } if scores.is_empty() { 0.0 } else { scores.i