// crates/context-graph-cli/src/commands/hooks/pre_tool_use.rs //! PreToolUse hook handler - FAST PATH //! //! # Performance Requirements //! - Timeout: 500ms per constitution.yaml hooks.timeout_ms.pre_tool_use //! - NO database access - fast path only //! - Return cached state only //! //! # Anti-Patterns (MUST NOT violate) //! - AP-50: No internal hooks //! - AP-51: Shell scripts call CLI //! - AP-53: Native hooks only use super::args::PreToolArgs; use super::error::{HookError, HookResult}; use super::memory_cache::{get_cached_memories, CachedMemory}; use super::types::{CoherenceState, HookInput, HookOutput, HookPayload, StabilityClassification}; use std::io::{self, BufRead}; use std::time::Instant; use tracing::debug; // ============================================================================ // Constants // ============================================================================ // ============================================================================ // Handler // ============================================================================ /// Handle pre_tool_use hook event (FAST PATH) /// /// # Performance /// MUST complete within 500ms. No database operations allowed. /// Returns cached coherence state with default values. /// /// # Arguments /// * `args` - CLI arguments from PreToolArgs /// /// # Returns /// * `HookOutput` with cached coherence state and optional tool guidance /// /// # Errors /// * `HookError::InvalidInput` - If required fields are missing pub fn handle_pre_tool_use(args: &PreToolArgs) -> HookResult<HookOutput> { let start = Instant::now(); // Parse input from stdin if requested let input: Option<HookInput> = if args.stdin { let stdin = io::stdin(); let mut input_str = String::new(); for line in stdin.lock().lines() { input_str.push_str(&line.map_err(|e| HookError::invalid_input(e.to_string()))?); } if input_str.is_empty() { None } else { Some( serde_json::from_str(&input_str) .map_err(|e| HookError::invalid_input(format!("Invalid JSON input: {}", e)))?, ) } } else { None }; // Extract tool_name from args or input payload let tool_name: Option<&str> = args.tool_name.as_deref().or_else(|| { input.as_ref().and_then(|i| match &i.payload { HookPayload::PreToolUse { tool_name, .. } => Some(tool_name.as_str()), _ => None, }) }); // Get tool-specific guidance (no database access) let guidance = tool_name.and_then(get_tool_guidance); // Get cached memories from user_prompt_submit (no network calls - fast path) let cached_memories = get_cached_memories(&args.session_id); debug!( session_id = %args.session_id, cached_count = cached_memories.len(), "PRE_TOOL: Retrieved cached memories" ); // Build cached coherence state with defaults // FAST PATH: We return default values, not computed ones // Real values would come from SessionCache (future task) let coherence = CoherenceState::default(); // Build stability classification with default values (using default crisis threshold 0.5) let stability_classification = StabilityClassification::from_value(coherence.topic_stability); // Calculate execution time let execution_time_ms = start.elapsed().as_millis() as u64; // Build output let mut output = HookOutput::success(execution_time_ms) .with_coherence_state(coherence) .with_stability_classification(stability_classification); // Build context injection from tool guidance + cached memories let context_injection = build_context_injection(guidance, &cached_memories, tool_name); if !context_injection.is_empty() { output = output.with_context_injection(context_injection); } Ok(output) } /// Build context injection from tool guidance and cached memories. /// /// Combines tool-specific guidance with relevant memories from the cache. /// This is pure computation with no I/O - safe for 500ms fast path (CLI logic ~100ms). /// /// # Arguments /// * `guidance` - Tool-specific guidance string /// * `memories` - Cached memories from user_prompt_submit /// * `tool_name` - Name of the tool (for relevance filtering) fn build_context_injection( guidance: Option<String>, memories: &[CachedMemory], tool_name: Option<&str>, ) -> String { let mut parts = Vec::new(); // Add tool guidance if present if let Some(guide) = guidance { parts.push(format!("## Tool Guidance
{}", guide)); } // Add cached memories if any exist and are relevant if !memories.is_empty() { // Filter memories by relevance to tool type (optional) let relevant_memories: Vec<&CachedMemory> = memories .iter() .filter(|m| is_memory_relevant_for_tool(m, tool_name)) .take(3) // Limit to top 3 for brevity in fast path .collect(); if !relevant_memories.is_empty() { let mut memory_section = String::from("## Relevant Context
