 = compute_coherence(snapshot); CoherenceState::new( coherence_level, snapshot.integration, snapshot.reflection, snapshot.differentiation, coherence_level, ) } /// R11: Build context injection from previous session's cached memories. /// /// When drift is near-zero (session continuation), inject the previous session's /// recent memories so Claude has immediate context of prior work. fn build_previous_session_context( prev_session_id: &str, cached: &[memory_cache::CachedMemory], ) -> String { let mut context = format!( "[Previous Session: {}]
