"); // Create two clearly different vectors let vec_a = vec![1.0, 0.0, 0.0, 0.0]; let vec_b = vec![0.0, 1.0, 0.0, 0.0]; let vec_c = vec![1.0, 0.0, 0.0, 0.0]; // Same as A fn cosine_sim(a: &[f32], b: &[f32]) -> f32 { let dot: f32 = a.iter().zip(b.iter()).map(|(x, y)| x * y).sum(); let norm_a: f32 = a.iter().map(|x| x * x).sum::<f32>().sqrt(); let norm_b: f32 = b.iter().map(|x| x * x).sum::<f32>().sqrt(); if norm_a == 0.0 || norm_b == 0.0 { return 0.0; } dot / (norm_a * norm_b) } let sim_ab = cosine_sim(&vec_a, &vec_b); let sim_ac = cosine_sim(&vec_a, &vec_c); println!("A = [1,0,0,0], B = [0,1,0,0], C = [1,0,0,0]"); println!("cosine(A, B) = {} (expected: 0.0)", sim_ab); println!("cosine(A, C) = {} (expected: 1.0)", sim_ac); assert!((sim_ab - 0.0).abs() < 0.001, "A and B are orthogonal"); assert!((sim_ac - 1.0).abs() < 0.001, "A and C are identical"); println!("✓ Cosine similarity computation is correct
"); } }

