ng, domain: String, content_a_snippet: String, content_b_snippet: String, expected_relationship: String, expected_has_connection: bool, actual_relationship: String, actual_has_connection: bool, actual_domain: String, actual_category: String, confidence: f32, direction: String, description: String, inference_time_ms: u64, is_correct: bool, domain_detection_correct: bool, #[serde(skip_serializing_if = "Option::is_none")] error: Option<String>, } /// Per-relationship type statistics. #[derive(Debug, Clone, Serialize, Default)] struct RelationshipTypeStats { correct: usize, total: usize, accuracy: f64, avg_confidence: f32, confidences: Vec<f32>, } /// Per-domain statistics. #[derive(Debug, Clone, Serialize)] struct DomainStats { domain: String, total_pairs: usize, correct: usize, accuracy: f64, domain_detection_correct: usize, domain_detection_accuracy: f64, avg_confidence: f32, avg_inference_time_ms: f64, relationship_breakdown: HashMap<String, RelationshipTypeStats>, } /// Latency percentiles. #[derive(Debug, Serialize)] struct LatencyStats { p50_ms: u64, p95_ms: u64, p99_ms: u64, min_ms: u64, max_ms: u64, avg_ms: f64, } /// Overall benchmark results. #[derive(Debug, Serialize)] struct BenchmarkResults { timestamp: String, model: String, total_pairs: usize, overall_accuracy: f64, overall_avg_confidence: f32, domain_results: HashMap<String, DomainStats>, cross_domain_false_positive_rate: f64, latency: LatencyStats, relationship_type_breakdown: HashMap<String, RelationshipTypeStats>, category_breakdown: HashMap<String, RelationshipTypeStats>, model_load_time_sec: f64, total_benchmark_time_sec: f64, } // ============================================================================ // HELPER FUNCTIONS // ============================================================================ fn truncate(s: &str, max_len: usize) -> String { let s = s.replace('
