#!/usr/bin/env python3 """Extract a broader SFT corpus from ALL real Shakespeare signals (no synthetic). Reads ~/.contextgraph/training/shakespeare_sft_all_signals.jsonl (45,750 raw records: 2,698 memories × 17 prompt angles + adversarial/curated variants) and produces a curated expansion: ~/.contextgraph/training/shakespeare_sft_broader.jsonl Target: 12,000-18,000 high-quality SFT examples from REAL Shakespeare text. Zero synthetic content. Every assistant response is cleaned verbatim text from his complete works. Pipeline: 1. Load all 45,750 raw signal records. 2. Strip play formatting from each assistant response (reuse logic from shakespeare_rebuild_all_data.py — scene headers, stage directions, character-name prefixes). 3. Drop records where cleaned response < MIN_RESPONSE_CHARS (default 120). 4. Replace system prompt with UNIFIED_SYSTEM (matches v2.1 dashboard + inference server). 5. Exclude records whose cleaned response is already in final_clean (deduplicate on SHA-1 of first 200 chars of cleaned response). 6. Cap to MAX_ANGLES_PER_MEMORY (default 7) prompt angles per memory — keeps diversity without flooding DPO with near-duplicate fragments. 7. Emit to broader.jsonl with stable _meta for provenance. Fail-fast: any missing input file → exit 1. Any record without the expected schema → logged to stderr + counted; does not corrupt output. Idempotent: if output file is complete (has completion marker), exits 0 immediately. """ from __future__ import annotations import argparse import hashlib import json import os import re import sys from collections import Counter, defaultdict from pathlib import Path from typing import Iterator HOME = Path.home() INPUT_ALL_SIGNALS = HOME / ".contextgraph/training/shakespeare_sft_all_signals.jsonl" INPUT_CLEAN = HOME / ".contextgraph/training/shakespeare_sft_final_clean.jsonl" OUTPUT = HOME / ".contextgraph/training/shakespeare_sft_broader.jsonl" MIN_RESPONSE_CHARS = 120 MAX_ANGLES_PER_MEMORY = 7 COMPLETION_MARKER = '{"_broader_corpus_complete": true}
' # Matches the v2.1 dashboard + inference server + cleaner scripts. UNIFIED_SYSTEM = ( "You are a knowledgeable assistant who writes EXCLUSIVELY in the style of " "William Shakespeare — early modern English using thee, thou, thy, thine, hast, " "dost, doth, ye, prithee, forsooth, hark, wherefore, methinks, 'tis, 'twas. " "You have full knowledge of ALL modern topics — science, technology, code, " "history, math, culture — and you explain them accurately and helpfully, but " "ALWAYS in Shakespearean prose or verse. Never refuse a topic. Never claim " "ignorance of modern things. Just answer everything in Shakespeare's voice." ) # Play-formatting strippers (ported verbatim from # scripts/shakespeare_rebuild_all_data.py & clean_training_data.py). SCENE_HEADER_RE = re.compile(r'^(SCENE|Scene|ACT|Act)\s+[IVXivx]+') STAGE_DIR_RE = re.compile( r'^(Enter|Exit|Exeunt|Re-enter|Alarum|Cornets|Flourish|Sennet|Trumpets|' r'Drums|Music|Retreat|Thunder|Lightning|Storm|Noise|Sound|Knocking|' r'A (room|street|hall|forest|garden|field|camp|prison|cave|tent|court))' ) CHAR_NAME_RE = re.compile(r'^[A-Z][A-Z\s]+\.\s*$') CHAR_NAME_PREFIX_RE = re.compile(r'^[A-Z][A-Z\s]+\.\s+') LOCATION_RE = re.compile(r'^[A-Z][a-z].*\.\s*$') SHAKE_MARKER_SET = frozenset([ "thou", "thee", "thy", "thine", "doth", "hath", "hast", "art", "methinks", "forsooth", "prithee", "hark", "love", "heart", "wherefore", ]) def strip_play_formatting(text: str) -> str: """Return text with scene headers, stage directions, character prefixes removed. Cleaned output is pure speech/verse.""" if not text: return "" out: list[str] = [] for line in text.split("
"): s = line.strip() if not s: continue if SCENE_HEADER_RE.match(s): continue if STAGE_DIR_RE.match(s): continue # Pure character headers like "HAMLET." or "KING LEAR." on their own line if CHAR_NAME_RE.match(s): continue # Location-only lines (short, capitalized, no Shakespeare vocabulary) if LOCATION_RE.match(s) and len(s) < 80: lower = s.lower() if not any(m in lower for m in SHAKE_MARKER_SET): continue # Parenthetical / bracketed stage directions spanning a whole line if (s.startswith('[') and s.endswith(']')) or (s.startswith('(') and s.endswith(')')): continue # Inline parentheticals/brackets s = re.sub(r'\[.*?\]', '', s) s = re.sub(r'\(.*?\)', '', s) # Leading character name prefix: "HAMLET. To be or not to be" s = CHAR_NAME_PREFIX_RE.sub('', s) s = s.strip() if s: out.append(s) return "
".join(out).strip() def sha1_key(text: str, n: int = 200) -> str: """Stable duplicate-detection key from first n chars of cleaned text.""" return hashlib.sha1(text[:n].encode('utf-8', errors='replace')).hexdigest() def load_existing_keys(path: Path) -> set[str]: """Return set of sha1-200 keys already present in final_clean. Empty if absent.""" keys: set[str] = set() if not path.is_file(): return keys with path.open() as f: for line in f: line

rest if not line.strip(): continue obj = json.loads(line) if obj.get("id") == rid: return obj raise TimeoutError(f"no reply for id={rid} within {timeout}s") def call(self, method, params=None, timeout=120.0): r = self._raw_call("tools/call", { "name": method, "arguments": params or {}, }, timeout=timeout) if r.get("result", {}).get("isError"): raise RuntimeError(f"tool '{method}' error: {r['result']['content'][0]['text']}") return json.loads(r["result"]["content"][0]["text"]) def close(self): self.s.close() def get_all_training_records(rpc, include_shape=True): """Pull ALL training records with full signal data.""" all_records = [] offset = 0 page_size = 500 while True: r = rpc.call("list_training_records", { "limit": page_size, "offset": offset, "includeShape": include_shape, }, timeout=60.0) records = r.get("records", []) if not records: break all_records.extend(records) offset += page_size if len(records) < page_size: break return all_records def get_memory_content(rpc, memory_id): """Get raw content for a memory.""" try: r = rpc.call("get_training_record", { "memoryId": memory_id, "includeVectors": False, }, timeout=30.0) if r.get("found") is False: return None return r.get("content", "") except Exception: return None def get_memory_fingerprint(rpc, memory_id): """Get full fingerprint with all embedder scores.""" try: r = rpc.call("get_memory_fingerprint", { "memoryId": memory_id, }, timeout=30.0) return r except Exception: return None def score_against_constellations(rpc, memory_id): """Score a memory against all Shakespeare constellations.""" try: r = rpc.call("score_against_constellation", { "memoryId": memory_id, "topK": 5, }, timeout=30.0) return r.get("scores", []) except Exception: return [] def get_typed_edges(rpc, memory_id): """Get typed edges for a memory.""" try: r = rpc.call("get_typed_edges", { "memoryId": memory_id, "direction": "outgoing", }, timeout=30.0) return r.get("edges", []) except Exception: return [] def classify_texture(shape): """Classify cross-correlation texture from the 13-dim shape vector.""" if not shape or len(shape) < 13: return "balanced" e1 = shape[0] if shape[0] else 0 # semantic e5 = shape[4] if shape[4] else 0 # causal e6 = shape[5] if shape[5] else 0 # keyword e8 = shape[7] if shape[7] else 0 # graph e10 = shape[9] if shape[9] else 0 # paraphrase e11 = shape[10] if shape[10] else 0 # entity if e1 > 0.3 and e5 > 0.3: return "high_semantic_causal" if e1 > 0.3 and e5 < 0.1: return "high_semantic_low_causal" if e6 > 0.3 and e10 < 0.1: return "high_keyword_low_paraphrase" if e11 > 0.3 and e8 > 0.3: return "high_entity_high_graph" if shape[6] and shape[6] > 0.3: # E7 code return "high_code_structure" if any(shape[i] and shape[i] > 0.3 for i in [1, 2, 3]): return "high_temporal" return "balanced" def make_sft(prompt, response, system_extra="", source="", meta=None): """Create an SFT training example.""" system = SYS_BASE if system_extra: system = f"{SYS_BASE}
{system_extra}" ex = { "messages": [ {"role": "system", "content": system}, {"role": "user", "content": prompt}, {"role": "assistant", "content": response}, ], "_meta": {"prompt_source": source}, } if meta: ex["_meta"].update(meta) return ex def generate_embedder_conditioned_examples(content, shape, enhanced_prompt, work_label, texture, meta_base): """Generate multiple SFT examples conditioned on different embedder signals. Each embedder dimension produces a different conditioning context, teaching the model WHICH ASPECT of the text matters for each prompt. """ examples = [] if not shape or len(shape) < 13: return examples # Extract first 200 chars for description generation snippet = content[:200].replace("
