Texture: {TEXTURE_LABELS.get(texture, texture)}.", source="embedder_E1_semantic", meta={**meta_base, "embedder": "E1", "score": shape[0]}, )) # E5 (causal) — cause-effect structure if shape[4] and shape[4] > 0.01: cond = f"[Causal structure: {shape[4]:.3f}] Emphasize cause-and-effect relationships." examples.append(make_sft( f"Explain the causes and consequences in: {enhanced_prompt}", content, system_extra=f"Style: {work_label}. {cond}", source="embedder_E5_causal", meta={**meta_base, "embedder": "E5", "score": shape[4]}, )) # E6 (keyword) — specific vocabulary if shape[5] and shape[5] > 0.01: cond = f"[Keyword density: {shape[5]:.3f}] Use specific, precise vocabulary." examples.append(make_sft( f"Using rich vocabulary, {enhanced_prompt.lower()}", content, system_extra=f"Style: {work_label}. {cond}", source="embedder_E6_keyword", meta={**meta_base, "embedder": "E6", "score": shape[5]}, )) # E8 (graph structural) — connections if shape[7] and shape[7] > 0.01: cond = f"[Structural connectivity: {shape[7]:.3f}] Show

#!/usr/bin/env python3 """Demo 3 — Auto-Genre Routing. User types a short prompt. We embed the prompt through the 13-embedder pipeline, score it against every Shakespeare constellation, and pick the work whose centroid is closest. Then we ask Gemma to continue in that work's voice, using the work's tightest member text as a few-shot example. Demonstrates the discovered geometric clustering in action: history-play prompts route to histories, lover prompts route to comedies/sonnets, revenge prompts route to tragedies. """ from __future__ import annotations import argparse import sys from pathlib import Path sys.path.insert(0, str(Path(__file__).parent)) from _gemma_shakespeare_lib import ( Rpc, GemmaClient, score_text, soft_delete, ) GENRE_HINTS = { "history": "Speak as a Shakespeare history play — kings, courts, succession, war.", "tragedy": "Speak as a Shakespeare tragedy — fate, mortality, hubris, grief.", "comedy": "Speak as a Shakespeare comedy — wit, mistaken identity, love, reconciliation.", "sonnet": "Speak as a Shakespeare sonnet — 14 lines iambic pentameter ABAB CDCD EFEF GG.", "poem": "Speak as a Shakespeare narrative poem — long-form mythological / allegorical verse.", } def classify_work(label: str) -> str: s = label.lower() if "sonnet" in s: return "sonnet" if any(k in s for k in ["henry", "richard", "king john"]): return "history" if "tragedy" in s or s.endswith("macbeth") or "lear" in s or "hamlet" in s or "othello" in s: return "tragedy" if any(k in s for k in ["lover", "venus", "lucrece", "phoenix", "passionate", "pilgrim"]): return "poem" return "comedy" def fetch_member_excerpt(rpc: Rpc, constellation_id: str, work_label: str, max_chars: int = 600) -> str | None: """Pull one representative excerpt from the work's session. NOTE: get_constellation currently returns an empty member_ids array even when member_count is non-zero (Phase 2 export gap). We work around this by using search_graph against the work's title — the top semantic hit is guaranteed t